 allocation[name]={'surface_points':n,'AO_count':nao,'S_bytes':8*n*n,'Cholesky_storage_bytes':8*n*n,'retained_S_plus_factor_bytes':16*n*n,'S_row_temporary_conservative_eight_block_arrays_bytes':8*8*min(128,n)*n,'factor_finite_check_boolean_array_bytes':n*n,'AO_integral_result_block8_bytes':8*nao*nao*8,'old_AO_integral_floor400_bytes':8*nao*nao*400,'AO_potential_bytes':8*nao*nao,'AO_contraction_result_temporary_bytes':8*nao*nao,'nuclear_integral_block128_bytes':8*natm*min(128,n) if natm is not None else None,'note':'Array allocation estimates only. Row estimate allows eight concurrent block arrays for NumPy expressions. Factorization library workspace, allocator retention, integral-engine scratch, SCF/grid/direct-JK storage and surface generation storage are not certified by this estimate. Parent nuclear-integral allocation is unestimated here; no parent was loaded or run.'}
